import React, { useState, useMemo, memo } from 'react';
import {
  Box,
  Typography,
  Select,
  MenuItem,
  FormControl,
} from '@mui/material';
import {
  PieChart,
  Pie,
  Cell,
  ResponsiveContainer,
  Tooltip,
  Legend,
} from 'recharts';
import { getYearOptions, getCurrentYear } from '../../utils/yearOptions';
import ChartTooltip from './ChartTooltip';



const RenderCustomizedLegend = (props) => {
  const { payload } = props;
  return (
    <Box
      sx={{
        display: 'flex',
        flexWrap: 'wrap',
        justifyContent: 'center',
        gap: '12px',
        mt: '10px',
      }}
    >
      {payload.map((entry, index) => (
        <Box
          key={`item-${index}`}
          sx={{ display: 'flex', alignItems: 'center', gap: '6px' }}
        >
          <Box
            sx={{
              width: 8,
              height: 8,
              borderRadius: '50%',
              bgcolor: entry.color,
            }}
          />
          <Typography
            sx={{
              fontSize: '0.72rem',
              color: '#AAAAAA',
              fontFamily: "'Montserrat', sans-serif",
              fontWeight: 500,
            }}
          >
            {entry.value}
          </Typography>
        </Box>
      ))}
    </Box>
  );
};


const DonutChart = ({
  title = 'Distribution',
  data = [],
  onYearChange,
  innerRadius = '70%',
  outerRadius = '90%',
}) => {
  const yearOptions = useMemo(() => getYearOptions(10), []);
  const [selectedYear, setSelectedYear] = useState(getCurrentYear());

  const accentColor = data.length > 0 ? data[0].color : '#4CC66E';

  const handleYearChange = (e) => {
    const yr = e.target.value;
    setSelectedYear(yr);
    if (onYearChange) onYearChange(yr);
  };

  const total = useMemo(() => data.reduce((acc, curr) => acc + (curr.value || 0), 0), [data]);

  return (
    <Box
      sx={{
        flex: { xs: 'none', sm: '1 1 0' },
        width: { xs: '100%', sm: 'auto' },
        minWidth: 0,
        background: '#001e08ff',
        backdropFilter: 'blur(12px)',
        border: '1px solid rgba(255, 255, 255, 0.08)',
        borderRadius: '24px',
        p: { xs: '12px 8px', sm: '24px 20px', md: '28px 24px' },
        display: 'flex',
        flexDirection: 'column',
        gap: { xs: '14px', md: '20px' },
        position: 'relative',
        overflow: 'hidden',
        transition: 'all 0.3s ease',
        '&:hover': {
          borderColor: 'rgba(76, 198, 110, 0.3)',
        },
        '&::before': {
          content: '""',
          position: 'absolute',
          top: '-15%',
          right: '-15%',
          width: '35%',
          height: '35%',
          background: `radial-gradient(circle, ${accentColor}10 0%, transparent 70%)`,
          pointerEvents: 'none',
        },
      }}
    >
      <Box
        sx={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: '12px',
          flexWrap: 'wrap',
          position: 'relative',
          zIndex: 1,
        }}
      >
        <Typography
          sx={{
            fontSize: { xs: '0.9rem', sm: '1.05rem', md: '1.15rem' },
            fontWeight: 700,
            color: '#FFFFFF',
            fontFamily: "'Montserrat', sans-serif",
            letterSpacing: '-0.02em',
          }}
        >
          {title}
        </Typography>

        {onYearChange && (
        <FormControl size="small" sx={{ minWidth: 100 }}>
          <Select
            value={selectedYear}
            onChange={handleYearChange}
            variant="outlined"
            MenuProps={{
                PaperProps: {
                  sx: {
                    bgcolor: 'rgba(28, 28, 28, 0.95)',
                    backdropFilter: 'blur(10px)',
                    border: '1px solid rgba(255,255,255,0.1)',
                    borderRadius: '14px',
                    mt: '6px',
                    boxShadow: '0 8px 32px rgba(0,0,0,0.5)',
                    '& .MuiMenuItem-root': {
                      fontSize: '0.8rem',
                      fontFamily: "'Montserrat', sans-serif",
                      color: 'rgba(255,255,255,0.7)',
                      borderRadius: '8px',
                      mx: '6px',
                      my: '2px',
                      '&:hover': { bgcolor: 'rgba(255,255,255,0.05)', color: '#fff' },
                      '&.Mui-selected': {
                        bgcolor: `${accentColor}20`,
                        color: accentColor,
                        fontWeight: 700,
                        '&:hover': { bgcolor: `${accentColor}30` },
                      },
                    },
                  },
                },
              }}
            sx={{
              height: '36px',
              bgcolor: 'rgba(255,255,255,0.05)',
              borderRadius: '12px',
              border: '1px solid rgba(255,255,255,0.08)',
              color: 'rgba(255,255,255,0.8)',
              fontFamily: "'Montserrat', sans-serif",
              fontSize: '0.8rem',
              fontWeight: 600,
              '& .MuiOutlinedInput-notchedOutline': { border: 'none' },
              '&:hover': { bgcolor: 'rgba(255,255,255,0.08)' },
              '&.Mui-focused': { borderColor: accentColor },
              '& .MuiSelect-icon': { color: 'rgba(255,255,255,0.5)' },
            }}
          >
            {yearOptions.map((opt) => (
              <MenuItem key={opt.value} value={opt.value}>
                {opt.label}
              </MenuItem>
            ))}
          </Select>
        </FormControl>
        )}
      </Box>

      {/* ── Chart ── */}
      <Box sx={{ width: '100%', height: { xs: 260, sm: 280, md: 300 }, position: 'relative', zIndex: 1 }}>
        <ResponsiveContainer width="100%" height="100%">
          <PieChart>
            <Pie
              data={data}
              cx="50%"
              cy="48%"
              innerRadius={innerRadius}
              outerRadius={outerRadius}
              paddingAngle={8}
              dataKey="value"
              stroke="none"
              animationBegin={200}
              animationDuration={1500}
            >
              {data.map((entry, index) => (
                <Cell key={`cell-${index}`} fill={entry.color} />
              ))}
            </Pie>
            <Tooltip content={<ChartTooltip />} />
            <Legend content={<RenderCustomizedLegend />} verticalAlign="bottom" />
          </PieChart>
        </ResponsiveContainer>

        {/* Center label */}
        <Box
          sx={{
            position: 'absolute',
            top: '48%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            textAlign: 'center',
            pointerEvents: 'none',
          }}
        >
          <Typography
            sx={{
              fontSize: '0.7rem',
              color: 'rgba(255,255,255,0.4)',
              fontWeight: 600,
              textTransform: 'uppercase',
              letterSpacing: '0.1em',
              mb: '-2px',
            }}
          >
            Total
          </Typography>
          <Typography
            sx={{
              fontSize: '1.4rem',
              color: '#fff',
              fontWeight: 800,
              fontFamily: "'Montserrat', sans-serif",
            }}
          >
            {total >= 1000 ? (total / 1000).toFixed(1) + 'k' : total}
          </Typography>
        </Box>
      </Box>
    </Box>
  );
};

export default memo(DonutChart);
